mapper.select:
select i.* from cost_boq_item i
where i.del_flag = '0' and i.batch_id = #{batchId}

    and i.item_code like concat('%', #{itemCode}, '%')


    and i.item_name like concat('%', #{itemName}, '%')


    and i.professional_type = #{professionalType}

order by i.source_row asc, i.id asc
